import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.G0y0PQA7.js";const o="/relio/shots/ko/preferences-general.png",b="/relio/shots/ko/preferences-shortcuts.png",f=JSON.parse('{"title":"환경 설정","description":"","frontmatter":{},"headers":[],"relativePath":"features/preferences.md","filePath":"features/preferences.md"}'),s={name:"features/preferences.md"};function n(l,t,k,i,h,g){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="환경-설정" tabindex="-1">환경 설정 <a class="header-anchor" href="#환경-설정" aria-label="Permalink to &quot;환경 설정&quot;">​</a></h1><p>도구 › 환경 설정…의 쪽별 항목을 설명합니다. 바꾸는 즉시 저장되고, 모든 문서에 함께 쓰입니다.</p><p>환경 설정 창 왼쪽에서 쪽을 고릅니다: <strong>일반</strong> · <strong>글로벌 그룹</strong> · <strong>번역 사전</strong> · <strong>Excel 템플릿</strong> · <strong>DB 연결</strong> · <strong>단축키</strong> · <strong>암호</strong> · <strong>설계 검사</strong>. 설정은 이 PC의 <code>%APPDATA%\\Relio</code>에 있고, 앱을 지웠다 다시 설치해도 남습니다.</p><h2 id="일반" tabindex="-1">일반 <a class="header-anchor" href="#일반" aria-label="Permalink to &quot;일반&quot;">​</a></h2><h3 id="화면" tabindex="-1">화면 <a class="header-anchor" href="#화면" aria-label="Permalink to &quot;화면&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>표시 언어</td><td><strong>OS 언어 따르기</strong> · 한국어 · English · 日本語 · 中文. 새 테이블 이름·기본 환경 이름·내보내기 문구도 이 언어를 따릅니다. 日本語·中文은 일부 문구만 번역되어 있고 나머지는 영어로 나옵니다.</td></tr><tr><td>테마</td><td>시스템 · 낮 · 밤 · 벚꽃 · 라벤더 · 숲 · 모카 · 서리. 창·메뉴·대화상자·패널은 테마 색을 따릅니다. 캔버스는 밝은 테마(낮·벚꽃·라벤더·숲)에서는 테마 색의 밝은 캔버스로, 어두운 테마(밤·모카·서리)에서는 기본 어두운 캔버스로 그리고, 테이블 같은 노드는 밝은 테마끼리·어두운 테마끼리 같은 색입니다. 내보내기·인쇄는 늘 밝은 색입니다. 벚꽃·라벤더·숲·모카·서리는 Windows 11에서 창 제목 줄도 테마 색입니다.</td></tr><tr><td>캔버스 색</td><td><strong>테마</strong> · <strong>낮</strong>. 낮을 고르면 어두운 테마에서도 캔버스를 밝게 그립니다. 노드에 지정한 색은 화면에서만 밝기를 맞추고 파일 값은 그대로입니다.</td></tr><tr><td>도구 막대</td><td><strong>Relio 기본</strong> · <strong>ERMaster식 (원래 전부)</strong>. ERMaster식은 원래 도구 막대 단추 전부와 원래 오른쪽 클릭 메뉴를 보입니다. 메뉴 막대는 같습니다.</td></tr></tbody></table><h3 id="파일" tabindex="-1">파일 <a class="header-anchor" href="#파일" aria-label="Permalink to &quot;파일&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>자동 백업 간격(분)</td><td>저장하지 않은 변경을 이 간격마다 백업합니다(기본 5). 0이면 끕니다. 백업은 설정 폴더의 <code>backup</code> 폴더에 파일마다 최근 10개를 둡니다.</td></tr><tr><td>시작할 때 마지막에 열려 있던 문서 다시 열기</td><td>끌 때 열려 있던 파일을 다음에 다시 엽니다.</td></tr><tr><td>Git에 맞춰 정렬해 저장</td><td>기본 켬. <a href="/relio/features/file#정렬해-저장">파일 › 정렬해 저장</a></td></tr></tbody></table><h3 id="업데이트" tabindex="-1">업데이트 <a class="header-anchor" href="#업데이트" aria-label="Permalink to &quot;업데이트&quot;">​</a></h3><p><strong>새 버전 자동 확인 (하루 한 번)</strong> — 켜면 하루 한 번 공개 Releases에서 버전 정보만 받습니다. 아래에 마지막 확인 결과(&quot;마지막 확인: … — 최신 버전입니다&quot;)가 보입니다. <a href="/relio/features/update">업데이트</a></p><h3 id="ai-도구" tabindex="-1">AI 도구 <a class="header-anchor" href="#ai-도구" aria-label="Permalink to &quot;AI 도구&quot;">​</a></h3><p><strong>AI 변경</strong> — <strong>바로 반영 (기본)</strong> · <strong>먼저 검토</strong>. 바로 반영은 저장하지 않은 편집과 겹치지 않으면 AI가 고친 것을 열린 문서에 바로 넣습니다(저장 전, 되돌리기 가능). 겹치거나 편집 중이면 합치기 탭에서 고릅니다. 먼저 검토는 늘 합치기 탭으로 엽니다. <a href="/relio/features/ai#먼저-검토와-합치기-탭">AI와 함께 쓰기 › 먼저 검토와 합치기 탭</a></p><h3 id="이-pc에-파일마다-기억한-것" tabindex="-1">이 PC에 파일마다 기억한 것 <a class="header-anchor" href="#이-pc에-파일마다-기억한-것" aria-label="Permalink to &quot;이 PC에 파일마다 기억한 것&quot;">​</a></h3><p>파일마다 대상 DB 버전 · DB 연결 · 암호 저장 방식(그리고 설계 검사 예외, 글 형식 내보내기 설정 등)을 이 PC에 기억합니다. 표에 파일·대상·연결이 보이고, 줄마다 <strong>지우기</strong>, 없어진 파일의 기록은 <strong>없는 파일 기록 지우기</strong>로 한꺼번에 정리합니다. 파일을 다른 곳으로 옮기면 기록은 새로 시작합니다.</p><h3 id="강조" tabindex="-1">강조 <a class="header-anchor" href="#강조" aria-label="Permalink to &quot;강조&quot;">​</a></h3><p>마우스 올림·선택 연결 강조, 나머지 흐리게, 흐림 정도, 강조 효과, 움직임 줄이기. <a href="/relio/features/find#강조-설정">찾기와 강조 › 강조 설정</a></p><h3 id="진단" tabindex="-1">진단 <a class="header-anchor" href="#진단" aria-label="Permalink to &quot;진단&quot;">​</a></h3><p><strong>진단 기록 남기기</strong> — 오류·시작 시간 같은 진단 정보를 이 PC의 설정 폴더에만 남깁니다(최근 7일). 인터넷으로 보내지 않고, 파일 내용·이름·경로는 들어가지 않습니다. 끄면 새 기록을 쓰지 않습니다. <strong>진단 기록 지우기</strong>로 지금까지의 기록을 지웁니다. <a href="/relio/features/troubleshooting#진단-기록">도움말과 문제 해결 › 진단 기록</a></p><figure class="shot" data-scene="preferences-general"><img src="'+o+'" alt="환경 설정 › 일반 — 화면·강조 묶음" loading="lazy"><figcaption>환경 설정 › 일반 — 화면·강조 묶음</figcaption></figure><h2 id="글로벌-그룹" tabindex="-1">글로벌 그룹 <a class="header-anchor" href="#글로벌-그룹" aria-label="Permalink to &quot;글로벌 그룹&quot;">​</a></h2><p>글로벌 그룹은 여러 파일이 함께 쓰는 컬럼 묶음입니다. 이 PC의 앱 설정에 저장되고, 문서에는 <strong>문서에 넣기</strong>로 복사합니다. 이 쪽에서는 목록(그룹 이름·컬럼 수)을 보고 **글로벌 그룹 관리…**로 고칩니다. <a href="/relio/features/model#그룹-관리·글로벌-그룹-관리">모델 메뉴 › 그룹 관리</a></p><h2 id="번역-사전" tabindex="-1">번역 사전 <a class="header-anchor" href="#번역-사전" aria-label="Permalink to &quot;번역 사전&quot;">​</a></h2><p>DB에서 가져올 때 물리명으로 논리명을 채우는 사전 목록입니다.</p><ul><li>번역 사전 파일은 UTF-8 글 파일로, 한 줄에 원어와 번역어를 쉼표로 나눠 적습니다(예: <code>customer,고객</code>). 쉼표가 없는 줄은 건너뜁니다.</li><li>표에 이름 · 항목 수 · 파일 위치가 보입니다. 앱에 포함된 내장 사전은 늘 맨 위입니다.</li><li><strong>새로 만들기…</strong> · <strong>추가(파일)…</strong> · <strong>제거</strong>(목록에서만 빼고 파일은 지우지 않음) · <strong>위로</strong> · <strong>아래로</strong> · <strong>파일 열기</strong>.</li><li>위에 있는 사전이 먼저 쓰입니다. 문서마다 쓸 사전은 모델 › 번역 관리…에서 고릅니다.</li></ul><h2 id="excel-템플릿" tabindex="-1">Excel 템플릿 <a class="header-anchor" href="#excel-템플릿" aria-label="Permalink to &quot;Excel 템플릿&quot;">​</a></h2><ul><li><strong>내장 템플릿</strong> — 앱에 들어 있는 템플릿입니다(한국어 — 테이블 정의서 등). **파일로 저장…**해 고쳐 쓴 뒤 <strong>사용자 템플릿으로 추가</strong>할 수 있습니다.</li><li><strong>사용자 템플릿</strong> — Excel 내보내기의 템플릿 목록에 함께 나옵니다. words·loops 시트와 템플릿 시트가 있는 <code>.xlsx</code> 또는 <code>.xls</code> 파일입니다. <strong>추가…</strong> · <strong>제거</strong>.</li></ul><p><a href="/relio/features/export#excel">내보내기 › Excel</a></p><h2 id="db-연결" tabindex="-1">DB 연결 <a class="header-anchor" href="#db-연결" aria-label="Permalink to &quot;DB 연결&quot;">​</a></h2><ul><li><strong>저장한 연결</strong> — DB 접속 창에서 저장한 연결의 이름 · 위치 · 사용자. <strong>이름 바꾸기</strong> · 지우기. 암호는 여기 저장하지 않습니다.</li><li><strong>DB 클라이언트</strong> — <strong>Oracle Instant Client 폴더</strong>(<code>oci.dll</code>이 있는 폴더의 전체 경로, 네트워크 경로 불가, 비우면 PATH에서 찾음, 바꾸면 다시 시작해야 적용), DB2·Informix·MS Access마다 <strong>ODBC 드라이버</strong>(드라이버 이름 또는 <code>.dll</code> 전체 경로, 비우면 기본 이름). 보안상 드라이버 파일과 Oracle 폴더는 여기 등록한 것만 씁니다.</li><li><strong>클라이언트 설정 저장</strong>으로 저장합니다.</li></ul><p><a href="/relio/features/database">DB 연동</a></p><h2 id="단축키" tabindex="-1">단축키 <a class="header-anchor" href="#단축키" aria-label="Permalink to &quot;단축키&quot;">​</a></h2><p>모든 단축키를 표(분류 · 동작 · 키)로 보고 바꿉니다. 도움말 › 단축키 목록…으로도 이 쪽이 열립니다.</p><ul><li><strong>바꾸기</strong>를 누른 뒤 새 키를 누릅니다(<kbd>Esc</kbd> = 취소). 바꾼 단축키는 메뉴에도 바로 보입니다.</li><li><strong>기본값</strong>으로 그 줄을 되돌리고, <strong>없애기</strong>로 키를 뺍니다. <strong>모두 기본값으로</strong>로 전부 되돌립니다.</li><li>다른 동작과 겹치는 키는 &quot;겹침: …&quot;으로 알립니다.</li><li>방향키(1칸 이동) · <kbd>Shift</kbd>+방향키(10칸) · <kbd>Tab</kbd>(다음 노드) · <kbd>Space</kbd>(누르고 끌어 화면 이동) · <kbd>Ctrl</kbd>+마우스 휠(확대·축소)은 바꿀 수 없는 <strong>고정</strong> 키입니다.</li></ul><h3 id="기본-단축키" tabindex="-1">기본 단축키 <a class="header-anchor" href="#기본-단축키" aria-label="Permalink to &quot;기본 단축키&quot;">​</a></h3><table tabindex="0"><thead><tr><th>분류</th><th>동작</th><th>키</th></tr></thead><tbody><tr><td>파일</td><td>새 다이어그램 / 열기 / 저장 / 다른 이름으로 저장</td><td><kbd>Ctrl</kbd>+<kbd>N</kbd> / <kbd>Ctrl</kbd>+<kbd>O</kbd> / <kbd>Ctrl</kbd>+<kbd>S</kbd> / <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>S</kbd></td></tr><tr><td>파일</td><td>닫기 / 인쇄</td><td><kbd>Ctrl</kbd>+<kbd>W</kbd> / <kbd>Ctrl</kbd>+<kbd>P</kbd></td></tr><tr><td>편집</td><td>되돌리기 / 다시 하기</td><td><kbd>Ctrl</kbd>+<kbd>Z</kbd> / <kbd>Ctrl</kbd>+<kbd>Y</kbd>(또는 <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>Z</kbd>)</td></tr><tr><td>편집</td><td>잘라내기 / 복사 / 붙여넣기 / 삭제 / 모두 선택</td><td><kbd>Ctrl</kbd>+<kbd>X</kbd> / <kbd>Ctrl</kbd>+<kbd>C</kbd> / <kbd>Ctrl</kbd>+<kbd>V</kbd> / <kbd>Delete</kbd> / <kbd>Ctrl</kbd>+<kbd>A</kbd></td></tr><tr><td>편집</td><td>찾기 막대 / 찾기 막대 일치 방식 바꾸기 / 검색</td><td><kbd>Ctrl</kbd>+<kbd>F</kbd> / <kbd>Alt</kbd>+<kbd>W</kbd> / <kbd>Ctrl</kbd>+<kbd>H</kbd></td></tr><tr><td>편집</td><td>이름 바로 고치기 / 정보 창 열기 / 도구 취소·선택 해제</td><td><kbd>F2</kbd> / <kbd>Enter</kbd> / <kbd>Esc</kbd></td></tr><tr><td>보기</td><td>확대 / 축소 / 100%</td><td><kbd>Ctrl</kbd>+<kbd>=</kbd> / <kbd>Ctrl</kbd>+<kbd>-</kbd> / <kbd>Ctrl</kbd>+<kbd>0</kbd></td></tr><tr><td>보기</td><td>오른쪽 패널 접기·펴기 / 아래 패널 접기·펴기 / 캔버스 최대화</td><td><kbd>Ctrl</kbd>+<kbd>Alt</kbd>+<kbd>B</kbd> / <kbd>Ctrl</kbd>+<kbd>J</kbd> / <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>M</kbd></td></tr><tr><td>보기</td><td>다음 문서 탭 / 이전 문서 탭</td><td><kbd>Ctrl</kbd>+<kbd>Tab</kbd> / <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>Tab</kbd></td></tr><tr><td>보기</td><td>비교: 묶음 전환</td><td><kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>G</kbd></td></tr><tr><td>도구</td><td>선택 도구 / 손 도구 / 테이블 / 뷰 / 1:N 관계 / 노트 / 카테고리</td><td><kbd>V</kbd> / <kbd>H</kbd> / <kbd>T</kbd> / <kbd>W</kbd> / <kbd>R</kbd> / <kbd>N</kbd> / <kbd>C</kbd></td></tr><tr><td>도움말</td><td>사용 설명서</td><td><kbd>F1</kbd></td></tr></tbody></table><p>그 밖에 <kbd>F3</kbd>·<kbd>Shift</kbd>+<kbd>F3</kbd>(찾기 결과), <kbd>F8</kbd>·<kbd>Shift</kbd>+<kbd>F8</kbd>(설계 검사 지적·합치기 충돌), 합치기 화면의 <kbd>1</kbd>·<kbd>2</kbd>·<kbd>3</kbd>·<kbd>Ctrl</kbd>+<kbd>Enter</kbd>가 있습니다.</p><figure class="shot" data-scene="preferences-shortcuts"><img src="'+b+'" alt="환경 설정 › 단축키 — 동작별 키와 바꾸기·기본값·없애기 단추" loading="lazy"><figcaption>환경 설정 › 단축키 — 동작별 키와 바꾸기·기본값·없애기 단추</figcaption></figure><h2 id="암호" tabindex="-1">암호 <a class="header-anchor" href="#암호" aria-label="Permalink to &quot;암호&quot;">​</a></h2><p>DB 접속 창에서 <strong>암호 기억</strong>으로 저장한 DB 암호 목록입니다. 암호는 Windows 자격 증명 관리자에 있고, 여기서는 목록을 보고 지울 수만 있습니다. <a href="/relio/features/database#암호를-저장하는-방식">DB 연동 › 암호를 저장하는 방식</a></p><h2 id="설계-검사" tabindex="-1">설계 검사 <a class="header-anchor" href="#설계-검사" aria-label="Permalink to &quot;설계 검사&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>캔버스에 표시</td><td>캔버스의 오류·경고 표시(보기 › 설계 검사 표시와 같음).</td></tr><tr><td>참고도 캔버스에 표시</td><td>참고 지적도 캔버스에 그립니다.</td></tr><tr><td>입력 중 추천</td><td>컬럼 정보 창의 후보 목록.</td></tr><tr><td>관계 이름 짝 (후보 강조·미리 채우기·1:N 뒤 알림)</td><td>관계 도구의 후보 강조와 같은 이름 컬럼 알림.</td></tr><tr><td>규칙 표</td><td>규칙마다 <strong>켬</strong> 체크와 <strong>심각도</strong>를 바꿉니다. <strong>기본값으로</strong>로 되돌립니다.</td></tr></tbody></table><p>이 PC의 예외는 파일별 기록에만 있고 팀과 나눠지지 않습니다. <a href="/relio/features/check">설계 검사와 추천</a></p>',42)])])}const u=d(s,[["render",n]]);export{f as __pageData,u as default};
